from abc import ABCMeta
from future.utils import with_metaclass


class MeasurementObject(with_metaclass(ABCMeta)):
    def __init__(self, idx, **args):
        self._id = idx
        self._args = args

    def id(self):
        return self._id

    @property
    def args(self):
        return self._args.items()

    def to_command(self):
        result = ' {}={}'.format(self.ID_ARG_NAME, self.id())
        result += ''.join(' {}={}'.format(name, value) for name, value in sorted(self.args))
        return result


class Measurement(MeasurementObject):
    ID_ARG_NAME = 'meas_id'

    def __init__(self, idx, **args):
        super(Measurement, self).__init__(idx, **args)
        self._phycells = []

    def phycells(self):
        return self._phycells

    def add_phycell(self, phycell):
        self._phycells.append(phycell)


class Phycell(MeasurementObject):
    ID_ARG_NAME = 'phycell_id'
